<script>
  import { onMount } from 'svelte';
  import { listen } from '@tauri-apps/api/event';
  import { api, authorize, bytes, command, exportText, items, json, media, native, saveFile } from './api.js';
  import { calculate } from './calculator.js';
  import { icons, routes, translate } from './i18n.js';
  import Details from './Details.svelte';

  let route = routes.includes(location.hash.slice(1)) ? location.hash.slice(1) : 'Home';
  let language = 'en', large = false, contrast = false, reduced = true, notifications = true, preferenceId = null;
  let error = '', notice = '', busy = false, connected = false, authKey = '', authNeeded = !native;
  let connectionChecked = false;
  let saveProgress = null;
  let privateTrash = [];
  let overview = {}, settings = {}, caps = {}, data = {}, query = '', sort = 'newest', category = '', cursor = null;
  let selected = null, previewError = false, confirmation = null, form = null, formValue = '', formName = '';
  let setup = false, setupStep = 0, hubName = '', copyFolder = '', importFolders = '', importScan = null, importChoice = 'later';
  let qr = null, pending = null, pairingDeadline = 0, remaining = 0;
  let records = [], note = null, noteTitle = '', noteBody = '', noteTrash = false, saveState = '', saveTimer, saveQueue = Promise.resolve(), noteRevision = 0;
  let address = 'https://www.wikipedia.org', tabs = [], previousTabs = [], bookmarks = [], downloads = [], permissionTab = null, websitePermissions = [], allowDownloads = false;
  let playlists = [], playlist = null, music = [], playing = null, shuffle = false, repeat = false;
  let expression = '', answer = '', history = [];
  let remoteSessions = [], remoteStatus = {};
  let loadGeneration = 0, mounted = false, alertIds = new Set(), alertsInitialized = false;
  $: t = key => translate(language, key);
  $: document.documentElement.lang = language;
  $: document.documentElement.dataset.large = String(large);
  $: document.documentElement.dataset.contrast = String(contrast);
  $: document.documentElement.dataset.reduced = String(reduced);
  $: musicTracks = playlist ? music.filter(f => json(playlist.body, { ids: [] }).ids?.includes(f.id)) : music;
  $: visibleNotes = records.filter(r => `${r.title}\n${r.body}`.toLowerCase().includes(query.toLowerCase()));
  const date = value => value ? new Date(value).toLocaleString(language === 'hi' ? 'hi-IN' : 'en-IN') : '—';
  const progress = row => row.size ? Math.min(100, Math.round(100 * row.bytes_verified / row.size)) : 0;
  const message = e => translate(language, String(e?.message || e));
  async function run(action, success = '') {
    if (busy) return; busy = true; error = ''; notice = '';
    try { const value = await action(); notice = success; return value; }
    catch (e) { error = message(e); }
    finally { busy = false; }
  }
  async function preference() {
    if (native) {
      const saved = await command('local_list', { kind: 'preference', query: '', trash: false });
      const row = saved.find(r => r.title === 'interface');
      if (row) { preferenceId = row.id; const p = json(row.body); language = p.language === 'hi' ? 'hi' : 'en'; large = !!p.large; contrast = !!p.contrast; reduced = p.reduced !== false; notifications = p.notifications !== false; }
    } else { try { const p = json(localStorage.getItem('hh-interface')); language = p.language === 'hi' ? 'hi' : 'en'; large = !!p.large; contrast = !!p.contrast; reduced = p.reduced !== false; } catch {} }
  }
  async function savePreferences() {
    const value = { language, large, contrast, reduced, notifications };
    try { if (native) preferenceId = (await command('local_save', { id: preferenceId, kind: 'preference', title: 'interface', body: JSON.stringify(value) })).id; else localStorage.setItem('hh-interface', JSON.stringify(value)); }
    catch (e) { error = message(e); }
  }
  async function loadPrivateTrash() { privateTrash = (await Promise.all(['note','playlist','bookmark'].map(kind => command('local_list',{kind,query:'',trash:true})))).flat(); }
  async function load() {
    const generation = ++loadGeneration, current = route;
    const put = (key, value) => { if (generation === loadGeneration) data = { ...data, [key]: value }; };
    if (['Notes','Browser','YouTube','Calculator'].includes(current)) {
      if (!native && current !== 'Calculator') return;
      if (current === 'Notes') records = await command('local_list', { kind: 'note', query: '', trash: noteTrash });
      if (current === 'Browser' || current === 'YouTube') { tabs = await command('browser_list'); previousTabs = await command('browser_previous'); bookmarks = await command('local_list', { kind: 'bookmark', query: '', trash: false }); downloads = await command('local_list', { kind: 'download', query: '', trash: false }); }
      return;
    }
    if (current === 'Home') {
      const values = await Promise.all([api('/api/overview'), api('/api/settings'), api('/api/alerts')]);
      if (generation !== loadGeneration) return;
      [overview, settings] = values; const alerts = items(values[2]); const fresh = alerts.find(a => !alertIds.has(a.id)); if (notifications && alertsInitialized && fresh) notice = fresh.message; alertIds = new Set(alerts.map(a => a.id)); alertsInitialized = true; put('alerts', alerts); connected = true; authNeeded = false;
      if (!settings.setup_complete && !mounted) { setup = true; hubName = settings.hub_name; copyFolder = settings.second_copy_root || ''; }
    } else if (current === 'Files' || current === 'Music') {
      const params = new URLSearchParams({ limit: '100', sort, ...(query ? { q: query } : {}), ...(current === 'Music' ? { category: 'music' } : category ? { category } : {}) });
      const value = await api(`/api/files?${params}`);
      if (generation !== loadGeneration) return;
      put('files', items(value)); cursor = value.next_cursor;
      if (current === 'Music') { music = items(value); if (native) playlists = await command('local_list', { kind: 'playlist', query: '', trash: false }); }
    } else if (current === 'Photos') {
      const value = await api('/api/photos/timeline?limit=100'); put('photos', items(value)); cursor = value.next_cursor;
      put('years', await api('/api/photos/years'));
    } else if (current === 'Transfers') { put('transfers', items(await api('/api/transfers'))); put('jobs', items(await api('/api/jobs'))); }
    else if (current === 'Storage') { put('storage', await api('/api/storage')); put('jobs', items(await api('/api/jobs'))); put('trash', items(await api('/api/trash'))); put('duplicates', items(await api('/api/duplicates'))); put('similar', items(await api('/api/similar'))); }
    else if (current === 'Devices') { put('devices', items(await api('/api/devices'))); pending = (await api('/api/pair/pending')).pending; }
    else if (current === 'Hardware') { put('hardware', await api('/api/hardware/audit')); put('network', await api('/api/network')); caps = await api('/api/capabilities'); }
    else if (current === 'Settings' || current === 'Remote') { if (current === 'Settings' && native) await loadPrivateTrash(); settings = await api('/api/settings'); hubName = settings.hub_name; copyFolder = settings.second_copy_root || ''; caps = await api('/api/capabilities'); if (current === 'Remote') { put('devices', items(await api('/api/devices'))); remoteStatus = await api('/api/remote/status'); remoteSessions = items(await api('/api/screen/sessions')); } }
    connected = true; connectionChecked = true; authNeeded = false;
  }
  async function refresh() { try { await load(); } catch (e) { error = message(e); if (!['Notes','Browser','YouTube','Calculator'].includes(route)) { connected = false; connectionChecked = true; } } }
  async function go(next) { if (busy) return; await flushNote(); if (saveState === 'error') return; route = next; query = ''; selected = null; confirmation = null; cursor = null; location.hash = next; await run(load); document.getElementById('content')?.focus(); }
  async function more() { if (!cursor) return; const key = route === 'Photos' ? 'photos' : 'files'; const params = new URLSearchParams({ cursor, limit: '100', sort, ...(query ? { q: query } : {}), ...(category ? { category } : {}) }); const value = await api(route === 'Photos' ? `/api/photos/timeline?${params}` : `/api/files?${params}`); data = { ...data, [key]: [...(data[key] || []), ...items(value)] }; cursor = value.next_cursor; if (route === 'Music') music = data.files; }
  async function mutate(path, method = 'POST', body) { await api(path, method, body); await load(); }
  function confirm(title, action, detail = '') { confirmation = { title, action, detail }; }
  async function accept() { const value = confirmation; confirmation = null; await run(value.action, t('Saved')); }
  async function pair() { await api('/api/pair/open', 'POST'); qr = await api('/api/pair/qr'); pairingDeadline = Date.now() + qr.expires_in * 1000; remaining = qr.expires_in; }
  async function finishSetup() { await api('/api/setup', 'POST', { hub_name: hubName, second_copy_root: copyFolder, setup_complete: true, remote_enabled: false }); setup = false; await load(); }
  async function saveSettings() { settings = await api('/api/settings', 'PATCH', { hub_name: hubName, second_copy_root: copyFolder, remote_enabled: settings.remote_enabled, screen_enabled: settings.screen_enabled, update_enabled: settings.update_enabled, update_manifest_url: settings.update_manifest_url || '', update_pubkey_hex: settings.update_pubkey_hex || '', backup_interval_minutes: Number(settings.backup_interval_minutes), scrub_interval_hours: Number(settings.scrub_interval_hours), second_copy_interval_minutes: Number(settings.second_copy_interval_minutes), wake_enabled: settings.wake_enabled, wake_time: settings.wake_time }); }
  function viewFile(file) { previewError = false; selected = file; }
  function fileForm(file, action) { form = { file, action }; formValue = action === 'Rename' ? file.name : ''; formName = file.name; }
  async function submitForm() {
    if (form.action === 'Rename') await api(`/api/files/${form.file.id}`, 'PATCH', { name: formValue });
    else await api(`/api/files/${form.file.id}/${form.action.toLowerCase()}`, 'POST', { rel_path: formValue, ...(form.action === 'Copy' ? { name: formName } : {}) });
    form = null; await load();
  }
  async function scanImport() { importScan = await api('/api/import/scan', 'POST', { paths: importFolders.split('\n').map(s => s.trim()).filter(Boolean) }); }
  async function startImport() { if (importChoice === 'later') { importScan = null; return; } await api('/api/import', 'POST', { paths: importFolders.split('\n').map(s => s.trim()).filter(Boolean), mode: importChoice === 'keep' ? 'keep' : 'copy' }); importScan = null; importFolders = ''; await load(); }
  function queueNote() { noteRevision++; saveState = 'saving'; clearTimeout(saveTimer); saveTimer = setTimeout(() => flushNote(), 650); }
  async function flushNote() {
    clearTimeout(saveTimer); if (!note || !['saving','error'].includes(saveState)) return saveQueue;
    const id = note.id, title = noteTitle, body = noteBody, revision = noteRevision;
    saveQueue = saveQueue.catch(() => {}).then(async () => {
      try { const row = await command('local_save', { id, kind: 'note', title, body }); records = records.map(r => r.id === row.id ? row : r); if (note?.id === id && noteRevision === revision) { note = row; saveState = 'saved'; } }
      catch (e) { saveState = 'error'; error = message(e); }
    }); return saveQueue;
  }
  async function chooseNote(row) { await flushNote(); if (saveState === 'error') return; note = row; noteTitle = row.title; noteBody = row.body; saveState = 'saved'; }
  async function newNote() { await flushNote(); if (saveState === 'error') return; const row = await command('local_save', { id: null, kind: 'note', title: t('Untitled note'), body: '' }); records = [row, ...records]; await chooseNote(row); }
  async function noteAction(restore) { await flushNote(); if (saveState === 'error') return; await command(restore ? 'local_restore' : 'local_trash', { id: note.id }); note = null; await load(); }
  async function noteFile(exportType) { await flushNote(); if (saveState === 'error') return; await command('note_export', { id: note.id, format: exportType }); }
  async function importNote() { const row = await command('note_import'); if (row) { noteTrash = false; await load(); await chooseNote(row); } }
  async function website(url = address, isolated = false) { const label = await command(isolated ? 'youtube_open' : 'browser_open', { url }); await load(); return label; }
  async function restoreTabs() { try { await command('browser_restore'); } finally { await load(); } }
  async function browserAction(tab, action) { await command('browser_action', { label: tab.label, action, url: action === 'navigate' ? address : null }); await load(); }
  async function bookmark(tab) { await command('local_save', { id: null, kind: 'bookmark', title: tab.title, body: JSON.stringify({ url: tab.url }) }); await load(); }
  function permissions(tab) { permissionTab = tab; websitePermissions = tab.permissions.map(p => p.split('|').pop()); allowDownloads = tab.downloads; }
  async function savePermissions() { await command('browser_permissions', { label: permissionTab.label, downloads: allowDownloads, permissions: websitePermissions }); permissionTab = null; await load(); }
  async function newPlaylist() { const row = await command('local_save', { id: null, kind: 'playlist', title: formValue.trim() || t('New playlist'), body: JSON.stringify({ ids: [] }) }); playlists = [row, ...playlists]; playlist = row; form = null; }
  async function addTrack(file, remove = false) { if (!playlist) return; let ids = json(playlist.body, { ids: [] }).ids || []; ids = remove ? ids.filter(id => id !== file.id) : [...new Set([...ids, file.id])]; playlist = await command('local_save', { id: playlist.id, kind: 'playlist', title: playlist.title, body: JSON.stringify({ ids }) }); playlists = playlists.map(row => row.id === playlist.id ? playlist : row); }
  function nextTrack(direction = 1) { const choices = musicTracks; if (!choices.length) return; const i = choices.findIndex(r => r.id === playing?.id); playing = choices[shuffle ? Math.floor(Math.random() * choices.length) : (i + direction + choices.length) % choices.length]; }
  function calc() { try { const value = calculate(expression); answer = String(value); history = [{ expression, answer }, ...history].slice(0, 30); error = ''; } catch (e) { error = message(e); } }
  async function unlock() { await authorize(authKey); authKey = ''; authNeeded = false; await load(); }
  async function diagnostics() { const value = await api('/api/diagnostics'); exportText(`homehub-diagnostics-${Date.now()}.json`, JSON.stringify(value, null, 2), 'application/json'); }
  async function stopSession(id) { await api(`/api/screen/sessions/${id}`, 'DELETE'); await load(); }
  function changeScope(device, scope, enabled) {
    const old = Array.isArray(device.scopes) ? device.scopes : String(device.scopes || '').split(',').filter(Boolean);
    const scopes = enabled ? [...new Set([...old, scope])] : old.filter(s => s !== scope);
    confirm(t('Device permissions'), () => mutate(`/api/devices/${device.id}`, 'PATCH', { scopes }), `${device.name}: ${scope}`);
  }
  function dialogFocus(node) {
    const previous = document.activeElement;
    node.tabIndex = -1;
    queueMicrotask(() => (node.querySelector('input,button,select,textarea') || node).focus());
    function keydown(event) {
      const modals = [...document.querySelectorAll('.modal')];
      if (modals.at(-1) !== node || event.key !== 'Tab') return;
      const focusable = [...node.querySelectorAll('a,button,input,select,textarea,[tabindex="0"]')].filter(el => !el.disabled && el.offsetParent !== null);
      const first = focusable[0], last = focusable.at(-1);
      if (!first) { event.preventDefault(); node.focus(); return; }
      if (event.shiftKey && (document.activeElement === first || document.activeElement === node)) { event.preventDefault(); last.focus(); }
      else if (!event.shiftKey && document.activeElement === last) { event.preventDefault(); first.focus(); }
    }
    node.addEventListener('keydown', keydown);
    return { destroy() { node.removeEventListener('keydown',keydown); if (previous?.isConnected) previous.focus(); } };
  }
  onMount(() => {
    let timer, unlisteners = [], cancelled = false;
    (async () => { try { await preference(); if (native) {
      unlisteners.push(await listen('shell-close-requested', async () => { try { await flushNote(); if (saveState !== 'error') await command('finish_close'); } catch (e) { error = message(e); } }));
      unlisteners.push(await listen('file-save-progress', event => { saveProgress = event.payload; }));
      unlisteners.push(await listen('file-save-finished', () => { saveProgress = null; }));
      await command('shell_ready');
    } await refresh(); mounted = true; if (!cancelled) timer = setInterval(async () => { remaining = Math.max(0, Math.ceil((pairingDeadline - Date.now()) / 1000)); if (qr && !remaining) { qr = null; pairingDeadline = 0; } if (document.hidden || busy) return; if (['Home','Transfers','Storage','Devices','Remote'].includes(route)) await refresh(); if (qr) try { pending = (await api('/api/pair/pending')).pending; } catch (e) { error = message(e); } }, 5000); } catch (e) { error = message(e); } })();
    const change = () => { const next = location.hash.slice(1); if (routes.includes(next) && next !== route) go(next); };
    const hiding = () => { if (document.hidden) flushNote(); else if (!busy && ['Home','Transfers','Storage','Devices','Remote'].includes(route)) refresh(); };
    window.addEventListener('hashchange', change); document.addEventListener('visibilitychange', hiding);
    return () => { cancelled = true; clearInterval(timer); clearTimeout(saveTimer); for (const unlisten of unlisteners) unlisten(); window.removeEventListener('hashchange', change); document.removeEventListener('visibilitychange', hiding); };
  });
</script>

<a class="skip" href="#content">{t('Skip to content')}</a>
<div class="shell">
  <aside>
    <a class="brand" href="#Home" on:click|preventDefault={() => go('Home')}><span class="brand-icon">⌂</span><span>Home Hub<small>{t('Your private home cloud')}</small></span></a>
    <nav aria-label="Home Hub">{#each routes as item, index}<button class:active={route === item} aria-current={route === item ? 'page' : undefined} on:click={() => go(item)}><span aria-hidden="true">{icons[index]}</span>{t(item)}</button>{/each}</nav>
    <div class="connection"><i class:online={connected}></i>{t(connected ? 'Connected locally' : connectionChecked ? 'Service unavailable' : 'Private apps ready')}<small>{native ? 'Windows' : 'Dashboard'}</small></div>
  </aside>
  <main id="content" tabindex="-1">
    <header><div><p class="eyebrow">HOME HUB</p><h1>{t(route)}</h1></div><div class="toolbar"><label class="language"><span class="sr-only">{t('Language')}</span><select bind:value={language} on:change={savePreferences}><option value="en">English</option><option value="hi">हिन्दी</option></select></label><button disabled={busy} on:click={() => run(load)}>{t('Refresh')}</button>{#if route === 'Home' || route === 'Devices'}<button class="primary" disabled={busy} on:click={() => run(pair)}>{t('Pair a device')}</button>{/if}</div></header>
    {#if error}<div class="banner error" role="alert"><span>{error}</span><button on:click={() => error = ''} aria-label={t('Close')}>×</button></div>{/if}
    {#if notice}<div class="banner success" role="status">{notice}</div>{/if}
    {#if busy}<p class="busy" role="status">{t('Saving…')}</p>{/if}
    {#if saveProgress}<section class="card" role="status"><div class="row"><span>{saveProgress.name} · {bytes(saveProgress.done)} / {bytes(saveProgress.total)}</span><button on:click={() => command('cancel_save',{id:saveProgress.id}).catch(e => error = message(e))}>{t('Cancel')}</button></div><progress max={saveProgress.total || 1} value={saveProgress.done} aria-label={saveProgress.name}></progress></section>{/if}
    {#if authNeeded && !native}<section class="card auth"><h2>{t('Unlock dashboard')}</h2><p>{t('No secret is included in this page. Use the installed app, or enter its local session key.')}</p><form on:submit|preventDefault={() => run(unlock)}><label>{t('Local session key')}<input type="password" autocomplete="off" bind:value={authKey} required /></label><button class="primary" disabled={busy}>{t('Unlock dashboard')}</button></form></section>{/if}

    {#if route === 'Home'}
      <section class="welcome"><div><h2>{overview.name || 'Home Hub'}</h2><p>{t('Your private home cloud')}</p></div><button disabled={busy || !connected} on:click={() => run(async () => { await api('/api/pause-sharing', 'POST', { paused: !settings.pause_sharing }); await load(); })}>{t(settings.pause_sharing ? 'Resume sharing' : 'Pause sharing')}</button></section>
      <div class="metrics"><div class="card"><span>{t('Free space')}</span><strong>{bytes(overview.free_bytes)}</strong><small>{bytes(overview.total_bytes)}</small></div><div class="card"><span>{t('Connected devices')}</span><strong>{overview.devices ?? '—'}</strong></div><div class="card"><span>{t('Active transfers')}</span><strong>{overview.active_transfers ?? '—'}</strong></div><div class="card"><span>{t('Verification')}</span><strong>{overview.copies ?? '—'}</strong><small>{t('A single drive is not a backup.')}</small></div></div>
      <div class="launcher">{#each routes.slice(1) as item, index}<button class="card app-tile" on:click={() => go(item)}><span aria-hidden="true">{icons[index + 1]}</span><strong>{t(item)}</strong></button>{/each}</div>
      <section class="card"><h2>{t('Alerts')}</h2>{#each data.alerts || [] as alert}<div class="row"><div><strong>{alert.message}</strong><small>{date(alert.created_at)}</small></div><button on:click={() => run(() => mutate(`/api/alerts/${alert.id}/ack`))}>{t('Confirm')}</button></div>{:else}<p class="muted">{t('Nothing here yet.')}</p>{/each}</section>
    {:else if route === 'Files'}
      <form class="toolbar filters" on:submit|preventDefault={() => run(load)}><label>{t('Search')}<input bind:value={query}/></label><label>{t('Category')}<select bind:value={category} on:change={() => run(load)}><option value="">{t('All')}</option>{#each [['photo','Photos'],['video','Videos'],['document','Documents'],['music','Music'],['backup','Backups'],['download','Downloads']] as cat}<option value={cat[0]}>{t(cat[1])}</option>{/each}</select></label><label>{t('Sort')}<select bind:value={sort} on:change={() => run(load)}><option value="newest">{t('Newest')}</option><option value="oldest">{t('Oldest')}</option><option value="name">{t('Name')}</option><option value="size">{t('Size')}</option></select></label><button>{t('Search')}</button></form>
      <section class="card table-wrap"><table><thead><tr><th>{t('Name')}</th><th>{t('Size')}</th><th>{t('Category')}</th><th><span class="sr-only">{t('Settings')}</span></th></tr></thead><tbody>{#each data.files || [] as file}<tr><td><button class="link" on:click={() => viewFile(file)}>{file.name}</button></td><td>{bytes(file.size)}</td><td>{t(({photo:'Photos',video:'Videos',document:'Documents',music:'Music',download:'Downloads',backup:'Backups'})[file.category] || file.category)}</td><td><div class="row-actions"><button on:click={() => run(() => saveFile(file))}>{t('Download')}</button><button on:click={() => fileForm(file,'Rename')}>{t('Rename')}</button><button on:click={() => fileForm(file,'Copy')}>{t('Copy')}</button><button on:click={() => fileForm(file,'Move')}>{t('Move')}</button><button on:click={() => confirm(t('Trash'), () => mutate(`/api/files/${file.id}`,'DELETE'),file.name)}>{t('Trash')}</button></div></td></tr>{:else}<tr><td colspan="4">{t('Nothing here yet.')}</td></tr>{/each}</tbody></table></section>
      {#if cursor}<button on:click={() => run(more)}>{t('Load more')}</button>{/if}
    {:else if route === 'Photos'}
      <p class="muted">{t('Phone storage cleanup requires verified copies and confirmation on your phone.')}</p>
      <div class="toolbar months">{#each items(data.years) as month}<span class="pill">{month.year} / {month.month} · {month.count}</span>{/each}</div>
      <section class="photo-grid">{#each data.photos || [] as photo}<button class="photo" on:click={() => viewFile({ ...photo, id: photo.file_id, mime: photo.type_ === 'video' ? 'video/mp4' : 'image/jpeg', name: photo.name || date(photo.taken_at) })}><img src={media(photo.file_id, 'thumb')} alt={photo.name || date(photo.taken_at)} loading="lazy"/><span>{date(photo.taken_at)}</span></button>{:else}<p>{t('Nothing here yet.')}</p>{/each}</section>{#if cursor}<button on:click={() => run(more)}>{t('Load more')}</button>{/if}
    {:else if route === 'Transfers'}
      <section class="card"><h2>{t('Transfers')}</h2>{#each data.transfers || [] as transfer}<article class="transfer"><div class="row"><div><strong>{transfer.name}</strong><small>{transfer.device} · {t(transfer.status)}{transfer.error_code ? ` · ${transfer.error_code}` : ''}</small></div>{#if ['open','verifying'].includes(transfer.status)}<button on:click={() => confirm(t('Cancel'), () => mutate(`/api/transfers/${transfer.id}`,'DELETE'),transfer.name)}>{t('Cancel')}</button>{/if}</div><progress max="100" value={progress(transfer)} aria-label={transfer.name}></progress><small>{bytes(transfer.bytes_verified)} / {bytes(transfer.size)}{transfer.rate_bps ? ` · ${bytes(transfer.rate_bps)}/s` : ''}{transfer.eta_secs != null ? ` · ${transfer.eta_secs} s` : ''}</small></article>{:else}<p>{t('Nothing here yet.')}</p>{/each}</section>
    {:else if route === 'Storage'}
      <div class="metrics"><div class="card"><span>{t('Free space')}</span><strong>{bytes(data.storage?.free_bytes)}</strong><small>{bytes(data.storage?.total_bytes)}</small></div><div class="card"><h2>{t('Protect your memories')}</h2><p>{t('A single drive is not a backup.')}</p><div class="toolbar"><button disabled={busy} on:click={() => run(() => mutate('/api/second-copy/run'))}>{t('Create second copy')}</button><button disabled={busy} on:click={() => run(() => mutate('/api/storage/scrub'))}>{t('Run integrity check')}</button></div></div></div>
      <section class="card"><h2>{t('Storage')}</h2><Details {t} value={data.storage}/></section>
      <section class="card"><h2>{t('Import a copy')}</h2><p>{t('Original files stay where they are.')}</p><label>{t('Folder paths (one per line)')}<textarea rows="3" bind:value={importFolders}></textarea></label><button disabled={busy || !importFolders.trim()} on:click={() => run(scanImport)}>{t('Scan folders')}</button>{#if importScan}<Details {t} value={importScan}/><fieldset><legend>{t('Import a copy')}</legend>{#each [['later','Later'],['keep','Keep in place'],['copy','Import a copy']] as choice}<label class="check"><input type="radio" bind:group={importChoice} value={choice[0]}/>{t(choice[1])}</label>{/each}</fieldset><button on:click={() => run(startImport)}>{t('Confirm')}</button>{/if}</section>
      <section class="card"><h2>{t('Move library')}</h2><p>{t('Original files stay where they are.')}</p><label>{t('Library folder')}<input bind:value={formValue}/></label><button disabled={!formValue.trim() || busy} on:click={() => confirm(t('Move library'),() => mutate('/api/library/move','POST',{path:formValue}),formValue)}>{t('Move library')}</button></section>
      <section class="card"><h2>{t('Trash')}</h2>{#each data.trash || [] as file}<div class="row"><span>{file.name} · {bytes(file.size)}</span><div class="toolbar"><button on:click={() => run(() => mutate(`/api/trash/${file.id}/restore`))}>{t('Restore')}</button><button class="danger" on:click={() => confirm(t('Delete permanently'), () => mutate(`/api/trash/${file.id}`,'DELETE'),file.name)}>{t('Delete permanently')}</button></div></div>{:else}<p>{t('Nothing here yet.')}</p>{/each}</section>
      <section class="card"><h2>{t('Review duplicates')}</h2>{#each data.duplicates || [] as group}<article><Details {t} value={group}/>{#each group.file_ids || [] as fileId}<button on:click={() => confirm(t('Review duplicates'), () => mutate(`/api/duplicates/${group.id}/resolve`,'POST',{keep_file_id:fileId}),fileId)}>{t('Keep in place')}: {fileId}</button>{/each}</article>{:else}<p>{t('Nothing here yet.')}</p>{/each}</section>
      <section class="card"><h2>{t('Similar photos')}</h2><p>{t('These are suggestions only. No photos are removed automatically.')}</p><div class="toolbar"><button disabled={busy} on:click={() => run(() => mutate('/api/duplicates/scan'))}>{t('Scan for similar photos')}</button><button disabled={busy} on:click={() => run(load)}>{t('Refresh')}</button></div>{#each data.similar || [] as group}<article>{#each group.files || [] as file}<div class="row"><img src={`/api/files/${file.id}/thumb`} alt={file.name} width="64" height="64" loading="lazy"/><span>{file.name}</span></div>{/each}</article>{:else}<p>{t('Nothing here yet.')}</p>{/each}</section>
    {:else if route === 'Notes'}
      {#if native}<p class="muted">{t('Private to this Windows user. Autosaves offline.')}</p><div class="toolbar"><button class="primary" on:click={() => run(newNote)}>{t('New note')}</button><button on:click={() => run(importNote)}>{t('Import note')}</button><label class="check"><input type="checkbox" bind:checked={noteTrash} on:change={() => run(async () => { await flushNote(); note = null; await load(); })}/>{t('Trash')}</label><label>{t('Search')}<input bind:value={query}/></label></div><div class="notes-layout"><section class="card note-list">{#each visibleNotes as row}<button class:active={note?.id === row.id} on:click={() => run(() => chooseNote(row))}><strong>{row.title || t('Untitled note')}</strong><small>{date(row.updated_at)}</small><p>{row.body.slice(0,90)}</p></button>{:else}<p>{t('Nothing here yet.')}</p>{/each}</section><section class="card editor">{#if note}<label>{t('Note title')}<input bind:value={noteTitle} maxlength="120" on:input={queueNote} readonly={noteTrash || busy}/></label><label class="note-body">{t('Note text')}<textarea bind:value={noteBody} on:input={queueNote} readonly={noteTrash || busy} spellcheck="true"></textarea></label><div class="toolbar"><span role="status">{saveState === 'saving' ? t('Saving…') : saveState === 'saved' ? t('Saved') : error}</span>{#if saveState === 'error'}<button on:click={flushNote}>{t('Retry')}</button>{/if}<button on:click={() => run(() => noteFile('md'))}>{t('Export Markdown')}</button><button on:click={() => run(() => noteFile('txt'))}>{t('Export text')}</button><button on:click={() => confirm(t(noteTrash ? 'Restore' : 'Trash'), () => noteAction(noteTrash),noteTitle)}>{t(noteTrash ? 'Restore' : 'Trash')}</button></div>{:else}<p>{t('New note')}</p>{/if}</section></div>{:else}<section class="card">{t('Private apps are available in the installed Windows app.')}</section>{/if}
    {:else if route === 'Browser' || route === 'YouTube'}
      <p>{t('Internet required. Website windows cannot access Home Hub or private apps.')}</p>{#if route === 'Browser'}<p>{t('Searches open DuckDuckGo in a separate website window.')}</p>{/if}{#if route === 'YouTube'}<section class="card"><h2>YouTube</h2><p>{t('YouTube opens in a separate private website session.')}</p><div class="toolbar"><button class="primary" on:click={() => run(() => website('https://www.youtube.com', true))} disabled={!native}>{t('Open website')}</button><button on:click={() => run(() => command('open_external',{url:'https://www.youtube.com'}))} disabled={!native}>{t('Open in default browser')}</button></div></section>{/if}
      {#if native}<form class="toolbar address" on:submit|preventDefault={() => run(() => website())}><label>{t('Address or search')}<input type="text" bind:value={address} placeholder="https://example.com or family photos" required/></label><button class="primary">{t('Open website')}</button><button type="button" on:click={() => run(() => command('open_external',{url:address}))}>{t('Open in default browser')}</button></form><section class="card"><h2>{t('Tabs')}</h2>{#if previousTabs.length && !tabs.length}<button class="primary" on:click={() => run(restoreTabs)}>{t('Restore previous tabs')}</button>{/if}{#each tabs as tab}<article class="browser-tab"><strong>{tab.title}</strong><small>{tab.url}</small><div class="toolbar">{#each [['back','Back'],['forward','Next'],['reload','Reload'],['focus','Focus'],['navigate','Open website'],['close','Close']] as action}<button on:click={() => run(() => browserAction(tab,action[0]))}>{t(action[1])}</button>{/each}<button on:click={() => run(() => bookmark(tab))}>{t('Bookmark')}</button><button on:click={() => permissions(tab)}>{t('Website permissions')}</button></div></article>{:else}<p>{t('Nothing here yet.')}</p>{/each}</section><section class="card"><h2>{t('Bookmarks')}</h2>{#each bookmarks as row}<div class="row"><button class="link" on:click={() => run(() => website(json(row.body).url))}>{row.title}</button><button on:click={() => run(async () => { await command('local_trash',{id:row.id}); await load(); })}>{t('Remove')}</button></div>{:else}<p>{t('Nothing here yet.')}</p>{/each}</section><section class="card"><h2>{t('Downloads')}</h2>{#each downloads as row}<div class="row"><span>{row.title} · {t(json(row.body).status)}</span><div class="toolbar"><button disabled={json(row.body).status !== 'complete'} on:click={() => run(() => command('save_download',{id:row.id}))}>{t('Save')}</button><button disabled={json(row.body).status === 'downloading'} on:click={() => confirm(t('Remove'),async () => { await command('discard_download',{id:row.id}); await load(); },row.title)}>{t('Remove')}</button></div></div>{:else}<p>{t('Nothing here yet.')}</p>{/each}</section><button class="danger" on:click={() => confirm(t('Clear website data'), async () => { await command('browser_clear'); await load(); })}>{t('Clear website data')}</button>{:else}<section class="card">{t('Private apps are available in the installed Windows app.')}</section>{/if}
    {:else if route === 'Music'}
      <div class="toolbar"><button class:active={!playlist} on:click={() => playlist = null}>{t('All music')}</button>{#each playlists as row}<button class:active={playlist?.id === row.id} on:click={() => playlist = row}>{row.title}</button>{/each}{#if native}<button on:click={() => { form = { action: 'playlist' }; formValue = ''; }}>{t('New playlist')}</button>{/if}<label class="check"><input type="checkbox" bind:checked={shuffle}/>{t('Shuffle')}</label><label class="check"><input type="checkbox" bind:checked={repeat}/>{t('Repeat')}</label></div>
      {#if playing}<section class="card player"><strong>{playing.name}</strong><audio src={media(playing.id)} controls autoplay loop={repeat} on:ended={() => nextTrack()}></audio><button on:click={() => nextTrack(-1)}>{t('Previous')}</button><button on:click={() => nextTrack()}>{t('Next')}</button></section>{/if}
      <section class="card">{#each musicTracks as track}<div class="row"><button class="link" on:click={() => playing = track}>{t('Play')} · {track.name}</button><span>{bytes(track.size)}</span>{#if playlist}<button on:click={() => run(() => addTrack(track,true))}>{t('Remove')}</button>{/if}</div>{:else}<p>{t('Nothing here yet.')}</p>{/each}</section>{#if playlist}<section class="card"><h2>{t('Add to playlist')}</h2>{#each music.filter(f => !json(playlist.body,{ids:[]}).ids?.includes(f.id)) as track}<button on:click={() => run(() => addTrack(track))}>{track.name}</button>{/each}<button class="danger" on:click={() => confirm(t('Remove'), async () => { await command('local_trash',{id:playlist.id}); playlist = null; await load(); })}>{t('Remove')} {playlist.title}</button></section>{/if}{#if cursor}<button on:click={() => run(more)}>{t('Load more')}</button>{/if}
    {:else if route === 'Calculator'}
      <section class="card calculator"><form on:submit|preventDefault={calc}><label>{t('Expression')}<input bind:value={expression} inputmode="decimal" placeholder="(24 + 36) / 2" autocomplete="off"/></label><output aria-live="polite">{answer || '0'}</output><div class="keypad">{#each ['(',')','%','/','7','8','9','*','4','5','6','-','1','2','3','+','0','.','^','='] as key}<button type="button" on:click={() => key === '=' ? calc() : expression += key}>{key}</button>{/each}</div><div class="toolbar"><button class="primary">{t('Calculate')}</button><button type="button" on:click={() => { expression = ''; answer = ''; }}>{t('Clear')}</button></div></form></section><section class="card"><h2>{t('History')}</h2>{#each history as row}<button class="history" on:click={() => expression = row.expression}>{row.expression} = {row.answer}</button>{/each}</section>
    {:else if route === 'Devices'}
      <section class="card">{#each data.devices || [] as device}<article class="device"><div class="row"><div><h2>{device.name}</h2><small>{device.platform} · {device.status === 'revoked' ? t('Revoke device') : date(device.last_seen_at)}</small></div><button class="danger" disabled={device.status === 'revoked'} on:click={() => confirm(t('Revoke device'),() => mutate(`/api/devices/${device.id}`,'DELETE'),device.name)}>{t('Revoke device')}</button></div><fieldset disabled={device.status === 'revoked'}><legend>{t('Device permissions')}</legend>{#each ['files','transfer','photos','remote','admin'] as scope}<label class="check"><input type="checkbox" checked={(Array.isArray(device.scopes) ? device.scopes : String(device.scopes || '').split(',')).includes(scope)} on:change={event => changeScope(device,scope,event.currentTarget.checked)}/>{t(scope === 'files' ? 'Files' : scope === 'transfer' ? 'Transfers' : scope === 'photos' ? 'Photos' : scope === 'remote' ? 'Remote' : 'Settings')}</label>{/each}</fieldset><button on:click={() => { form = { action:'device',file:device }; formValue = device.name; }}>{t('Rename')}</button></article>{:else}<p>{t('Nothing here yet.')}</p>{/each}</section>
    {:else if route === 'Hardware'}
      <section class="card"><h2>{t('Hardware')}</h2><button disabled={busy} on:click={() => run(async () => { data = { ...data, hardware: await api('/api/hardware/audit/run','POST') }; })}>{t('Run hardware check')}</button><Details {t} value={data.hardware}/></section><section class="card"><h2>{t('Connected locally')}</h2><Details {t} value={data.network}/><p>{t('Wake support varies by laptop. Files stay queued when the Hub is asleep.')}</p><Details {t} value={caps}/></section>
    {:else if route === 'Remote'}
      <section class="card"><h2>{t('Remote')}</h2><p>{t('Remote is off until you grant a device permission.')}</p><label class="check"><input type="checkbox" bind:checked={settings.remote_enabled} disabled={!caps.remote} on:change={() => run(saveSettings)}/>{t('Enable remote control')}</label><Details {t} value={remoteStatus}/><button on:click={() => go('Devices')}>{t('Device permissions')}</button><p>{t('Wake support varies by laptop. Files stay queued when the Hub is asleep.')}</p></section><section class="card"><h2>{t('Remote sessions')}</h2><p>{t('Start Cast on your phone to show its screen on this laptop. Video only; the phone keeps control.')}</p>{#each remoteSessions as session}<div class="row"><span>{session.device_name || session.device_id || session.id} · {t(session.direction)} · {t(session.state || session.status)}</span><button on:click={() => run(() => stopSession(session.id))}>{t('Stop session')}</button></div>{:else}<p>{t('Nothing here yet.')}</p>{/each}</section>
    {:else if route === 'Settings'}
      <section class="card"><h2>{t('Settings')}</h2><form on:submit|preventDefault={() => run(saveSettings,t('Saved'))}><label>{t('Hub name')}<input bind:value={hubName} maxlength="120" required/></label><label>{t('Library folder')}<input value={settings.library_root || ''} readonly/></label><label>{t('Second-copy folder')}<input bind:value={copyFolder}/></label><label>{t('Backup interval (minutes)')}<input type="number" min="1" max="10080" bind:value={settings.backup_interval_minutes}/></label><label>{t('Scrub interval (hours)')}<input type="number" min="1" max="720" bind:value={settings.scrub_interval_hours}/></label><label>{t('Second-copy interval (minutes)')}<input type="number" min="1" max="43200" bind:value={settings.second_copy_interval_minutes}/></label><label class="check"><input type="checkbox" bind:checked={settings.screen_enabled}/>{t('Allow screen sharing')}</label><label class="check"><input type="checkbox" bind:checked={settings.wake_enabled}/>{t('Request scheduled wake')}</label>{#if settings.wake_enabled}<label>{t('Wake time')}<input type="time" bind:value={settings.wake_time}/></label>{/if}<label class="check"><input type="checkbox" bind:checked={settings.update_enabled}/>{t('Check for signed updates')}</label>{#if settings.update_enabled}<label>{t('Update manifest URL')}<input type="url" bind:value={settings.update_manifest_url}/></label><label>{t('Update public key')}<input maxlength="64" bind:value={settings.update_pubkey_hex}/></label>{/if}<button class="primary" disabled={busy}>{t('Save')}</button></form><button on:click={() => { setup = true; setupStep = 0; }}>{t('Setup')}</button></section><section class="card"><h2>{t('Language')}</h2><label>{t('Language')}<select bind:value={language} on:change={savePreferences}><option value="en">English</option><option value="hi">हिन्दी</option></select></label>{#each [['large','Larger text'],['contrast','High contrast'],['reduced','Reduce motion'],['notifications','Notifications in this app']] as option}<label class="check"><input type="checkbox" checked={option[0] === 'large' ? large : option[0] === 'contrast' ? contrast : option[0] === 'reduced' ? reduced : notifications} on:change={event => { if (option[0] === 'large') large = event.currentTarget.checked; else if (option[0] === 'contrast') contrast = event.currentTarget.checked; else if (option[0] === 'reduced') reduced = event.currentTarget.checked; else notifications = event.currentTarget.checked; savePreferences(); }}/>{t(option[1])}</label>{/each}</section><section class="card"><h2>{t('Protect your memories')}</h2><p>{t('Turn on BitLocker in Windows to protect data at rest.')}</p><p>{t('A single drive is not a backup.')}</p><div class="toolbar"><button on:click={() => run(diagnostics)}>{t('Diagnostics export')}</button>{#if native}<button on:click={() => run(async () => { await flushNote(); await command('local_export'); })}>{t('Export private apps')}</button><button on:click={() => run(async () => { await command('local_import'); await loadPrivateTrash(); })}>{t('Import private apps')}</button>{/if}</div></section>
    {/if}

    {#if route === 'Settings' && native}<section class="card"><h2>{t('Private app trash')}</h2>{#each privateTrash as row}<div class="row"><span>{row.title} · {t(row.kind)}</span><div class="toolbar"><button on:click={() => run(async () => { await command('local_restore',{id:row.id}); await loadPrivateTrash(); })}>{t('Restore')}</button><button class="danger" on:click={() => confirm(t('Delete permanently'),async () => { await command('local_purge',{id:row.id}); await loadPrivateTrash(); },row.title)}>{t('Delete permanently')}</button></div></div>{:else}<p>{t('Nothing here yet.')}</p>{/each}</section>{/if}
    {#if ['Transfers','Storage'].includes(route)}<section class="card"><h2>{t('Jobs')}</h2>{#each data.jobs || [] as job}<article class="transfer"><div class="row"><strong>{t(job.kind)} · {t(job.status)}</strong>{#if ['queued','running'].includes(job.status)}<button disabled={job.cancel_requested} on:click={() => confirm(t('Cancel'),() => mutate(`/api/jobs/${job.id}`,'DELETE'),job.kind)}>{t('Cancel')}</button>{/if}</div><progress max={Math.max(1,job.total)} value={job.done} aria-label={job.kind}></progress><small>{job.done} / {job.total}{job.error ? ` · ${job.error}` : ''}</small>{#if job.result}<Details {t} value={job.result}/>{/if}</article>{:else}<p>{t('Nothing here yet.')}</p>{/each}</section>{/if}
  </main>
</div>

{#if setup}<div class="overlay"><div use:dialogFocus class="modal" role="dialog" aria-modal="true" aria-labelledby="setup-title"><h2 id="setup-title">{t('Welcome to Home Hub')}</h2><p>{setupStep + 1} / 3</p>{#if setupStep === 0}<label>{t('Hub name')}<input bind:value={hubName} maxlength="120"/></label><label>{t('Library folder')}<input value={settings.library_root || ''} readonly/></label><p>{t('Original files stay where they are.')}</p>{:else if setupStep === 1}<h3>{t('Protect your memories')}</h3><p>{t('A single drive is not a backup.')}</p><label>{t('Second-copy folder')} · {t('Optional')}<input bind:value={copyFolder}/></label><p>{t('Choose an external drive for a second copy.')}</p><p>{t('Turn on BitLocker in Windows to protect data at rest.')}</p>{:else}<h3>{t('Pair a device')}</h3><p>{t('Remote is off until you grant a device permission.')}</p><button on:click={() => run(pair)}>{t('Pair a device')}</button>{/if}<div class="toolbar">{#if setupStep > 0}<button on:click={() => setupStep--}>{t('Back')}</button>{/if}{#if setupStep < 2}<button class="primary" disabled={!hubName.trim()} on:click={() => setupStep++}>{t('Next')}</button>{:else}<button class="primary" disabled={busy} on:click={() => run(finishSetup)}>{t('Finish setup')}</button>{/if}<button on:click={() => setup = false}>{t('Later')}</button></div></div></div>{/if}
{#if qr}<div class="overlay"><div use:dialogFocus class="modal pairing" role="dialog" aria-modal="true" aria-labelledby="pair-title"><h2 id="pair-title">{t('Pair a device')}</h2>{#if qr.qr}<img src={qr.qr} alt={t('Pair a device')}/>{/if}<p>{t('Manual code')}: <strong>{qr.manual_code}</strong></p><p>{t('Pairing expires in')} {remaining} {t('seconds')}</p><button on:click={() => qr = null}>{t('Close')}</button></div></div>{/if}
{#if pending}<div class="overlay"><div use:dialogFocus class="modal" role="dialog" aria-modal="true" aria-labelledby="pending-title"><h2 id="pending-title">{t('Device permissions')}</h2><Details {t} value={{ name:pending.device_name || pending.name,platform:pending.platform }}/><div class="toolbar"><button class="primary" on:click={() => run(async () => { await api('/api/pair/confirm','POST',{request_id:pending.request_id,allow:true}); pending = null; })}>{t('Approve')}</button><button on:click={() => run(async () => { await api('/api/pair/confirm','POST',{request_id:pending.request_id,allow:false}); pending = null; })}>{t('Deny')}</button></div></div></div>{/if}
{#if selected}<div class="overlay"><div use:dialogFocus class="modal viewer" role="dialog" aria-modal="true" aria-labelledby="viewer-title"><div class="row"><h2 id="viewer-title">{selected.name}</h2><button on:click={() => selected = null}>{t('Close')}</button></div>{#if selected.mime?.startsWith('image/')}<img src={media(selected.id)} alt={selected.name} on:error={() => previewError = true}/>{:else if selected.mime?.startsWith('video/')}<video controls autoplay src={media(selected.id)} aria-label={selected.name} on:error={() => previewError = true}></video>{:else if selected.mime?.startsWith('audio/')}<audio controls src={media(selected.id)} aria-label={selected.name} on:error={() => previewError = true}></audio>{:else}<Details {t} value={{category:selected.category,size:bytes(selected.size),created:date(selected.created_at)}}/>{/if}{#if previewError}<p role="status">{t('This format cannot be previewed here. Download it to open in another app.')}</p>{/if}<button on:click={() => run(() => saveFile(selected))}>{t('Download')}</button></div></div>{/if}
{#if confirmation}<div class="overlay"><div use:dialogFocus class="modal" role="alertdialog" aria-modal="true" aria-labelledby="confirm-title"><h2 id="confirm-title">{confirmation.title}</h2><p>{confirmation.detail}</p><p>{t('This action changes stored data.')}</p><div class="toolbar"><button class="primary" disabled={busy} on:click={accept}>{t('Confirm')}</button><button on:click={() => { confirmation = null; refresh(); }}>{t('Cancel')}</button></div></div></div>{/if}
{#if form}<div class="overlay"><div use:dialogFocus class="modal" role="dialog" aria-modal="true" aria-labelledby="form-title"><h2 id="form-title">{t(form.action === 'playlist' ? 'New playlist' : form.action === 'device' ? 'Rename' : form.action)}</h2><form on:submit|preventDefault={() => run(form.action === 'playlist' ? newPlaylist : form.action === 'device' ? async () => { await api(`/api/devices/${form.file.id}`,'PATCH',{name:formValue}); form = null; await load(); } : submitForm)}><label>{t(['Move','Copy'].includes(form.action) ? 'Library folder' : 'Name')}<input bind:value={formValue} required/></label>{#if form.action === 'Copy'}<label>{t('Name')}<input bind:value={formName} required/></label>{/if}<div class="toolbar"><button class="primary">{t('Save')}</button><button type="button" on:click={() => form = null}>{t('Cancel')}</button></div></form></div></div>{/if}
{#if permissionTab}<div class="overlay"><div use:dialogFocus class="modal" role="dialog" aria-modal="true" aria-labelledby="permissions-title"><h2 id="permissions-title">{t('Website permissions')}</h2><p>{permissionTab.url}</p><p>{t('Changing permissions resets this tab’s website session and reloads the page.')}</p><fieldset><legend>{t('Website permissions')}</legend>{#each ['camera','microphone','location','notifications','protected_media'] as permission}<label class="check"><input type="checkbox" bind:group={websitePermissions} value={permission}/>{t(permission)}</label>{/each}<label class="check"><input type="checkbox" bind:checked={allowDownloads}/>{t('Allow downloads')}</label></fieldset><div class="toolbar"><button class="primary" on:click={() => run(savePermissions)}>{t('Save')}</button><button on:click={() => permissionTab = null}>{t('Cancel')}</button></div></div></div>{/if}
